import{_ as n,o as r,c as a,a3 as t}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"UIX Forge","description":"Überblick über UIX Forge, Molds, Foundries und Sparks.","frontmatter":{"title":"UIX Forge","description":"Überblick über UIX Forge, Molds, Foundries und Sparks."},"headers":[],"relativePath":"projects/uix/forge/index.md","filePath":"projects/uix/forge/index.md","lastUpdated":1792859421000}'),i={name:"projects/uix/forge/index.md"};function o(d,e,s,l,u,c){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="uix-forge" tabindex="-1">UIX Forge <a class="header-anchor" href="#uix-forge" aria-label="Permalink to &quot;UIX Forge&quot;">​</a></h1><p>UIX Forge erzeugt Home-Assistant-Elemente dynamisch. Du definierst eine <code>forge</code>-Konfiguration, ein Ziel-<code>element</code> und optional zusätzliche <code>sparks</code>, die Verhalten oder Darstellung erweitern.</p><p>Unterstützt werden die Molds <code>card</code>, <code>badge</code>, <code>row</code>, <code>picture-element</code>, <code>section</code>, <code>footer</code> und <code>card-feature</code>. Cross-Context-Molds erlauben, ein Element in einem anderen Kontext zu verwenden, zum Beispiel eine Karte als Zeile in einer Entities-Karte.</p><p>Ab <strong>UIX 9.0.0-beta.0</strong> ermöglicht die <a href="./forge#layered-configuration">geschichtete Konfiguration</a>, native Templates des eingebetteten Elements unverändert zu erhalten und darüber eine separate Forge-Konfiguration zu legen. Sie gilt für alle Molds und benötigt keinen visuellen Editor.</p><p>Für die vollständige Konfigurationsreferenz siehe <a href="./forge">Forge-Referenz</a>.</p><p>Die Vorschau <strong>9.0.0-beta.2</strong> ergänzt den <a href="./forge#visual-editor-cards-and-badges">visuellen Editor für Karten und Badges</a>. Für unverändert durchzureichende native Einstellungen und Templates steht <code>element_base</code>; nur von Forge geänderte Werte gehören nach <code>element</code>. Das gilt weiterhin für jeden Mold. Foundry-<code>element_base</code> ist editorerhaltener Quelltext: über den Export-Reiter erzeugen und bei späterem Bearbeiten erhalten. Die genaue Typanker-Regel steht unter <a href="./foundries#foundry-typ-mit-dem-nativen-editor-verwenden">Foundries</a>.</p><h2 id="foundries" tabindex="-1">Foundries <a class="header-anchor" href="#foundries" aria-label="Permalink to &quot;Foundries&quot;">​</a></h2><p>Eine <strong>Foundry</strong> ist eine wiederverwendbare UIX-Forge-Konfiguration. Damit kannst du <code>forge</code>, <code>element</code> und <code>uix</code> einmal definieren und an vielen Stellen wiederverwenden. Ab UIX 9.0.0-beta.0 können Foundries auch <code>element_base</code> bereitstellen; eine aufgelöste Basis aktiviert die geschichtete Konfiguration. <code>element_disabled_paths</code> bleibt ausschließlich lokal an der jeweiligen Forge-Instanz.</p><p>Mehr dazu: <a href="./foundries">Foundries</a></p><h2 id="sparks" tabindex="-1">Sparks <a class="header-anchor" href="#sparks" aria-label="Permalink to &quot;Sparks&quot;">​</a></h2><p>Sparks sind optionale Bausteine in <code>forge.sparks</code>. Jeder Spark hat einen <code>type</code> und eigene Optionen.</p><p>Verfügbare Sparks:</p><ul><li>💬 <a href="./sparks/tooltip">Tooltip</a> - Tooltip an ein Element hängen.</li><li>:material-button-cursor: <a href="./sparks/button">Button</a> - Button mit Aktionen einfügen.</li><li>🏷️ <a href="./sparks/attribute">Attribute</a> - Attribute hinzufügen, ersetzen oder entfernen.</li><li>⚡ <a href="./sparks/event">Event</a> - DOM-Events aufnehmen und als Template-Variablen nutzen.</li><li>⭐ <a href="./sparks/tile-icon">Tile Icon</a> - <code>ha-tile-icon</code> ergänzen.</li><li>🛡️ <a href="./sparks/state-badge">State Badge</a> - Status-Badge einfügen.</li><li>:material-grid: <a href="./sparks/grid">Grid</a> - CSS Grid auf Container anwenden.</li><li>🔍 <a href="./sparks/search">Search</a> - Elemente per CSS-Selektor suchen und verändern.</li><li>:material-map: <a href="./sparks/map">Map</a> - Kartenansicht bewahren sowie Touren, Verlaufsregler und Entity-Filter mit konfigurierbaren Positionen ergänzen.</li><li>:material-lock: <a href="./sparks/lock">Lock</a> - Interaktion per Sperre schützen.</li><li>:material-star-four-points-outline: <a href="./sparks/overlay-icon">Overlay Icon</a> - Icon über ein Element legen.</li><li>:material-image-outline: <a href="./sparks/background">Background</a> - Hintergrundfarbe, Bild, Video oder Kamera einfügen.</li><li>:material-palette: <a href="./sparks/theme">Theme</a> - Theme auf ein Element anwenden.</li><li><a href="./sparks/form">Formular</a> - Home-Assistant-Formular mit optionalen Absende- und Leeren-Aktionen.</li></ul>',13)])])}const f=n(i,[["render",o]]);export{g as __pageData,f as default};
